package br.radio.zapdmr;

import android.content.*;
import android.media.*;
import android.os.Build;
import org.json.JSONObject;

/** Native routes on the existing engine. A preferred device is a request, not proof of capture. */
final class CarAudio {
    static volatile String observedOutput="",observedInput="",routeStatus="Padrão do Android; microfone ainda não verificado.";
    static volatile int observedInputId,observedInputType;
    static volatile boolean legacyScoConnected;
    private static Integer previousMode;private static AudioDeviceInfo previousCommunication;
    static boolean hasOverride(){return previousMode!=null;}
    static AudioManager manager(Context c){return (AudioManager)c.getSystemService(Context.AUDIO_SERVICE);}
    static AudioDeviceInfo device(Context c,int id,boolean input){for(AudioDeviceInfo d:manager(c).getDevices(input?AudioManager.GET_DEVICES_INPUTS:AudioManager.GET_DEVICES_OUTPUTS))if(d.getId()==id)return d;return null;}
    static String describe(AudioDeviceInfo d){return d==null?"Não verificado":d.getProductName()+" · "+CarAudioTypes.label(d.getType())+" · id "+d.getId();}
    static AudioDeviceInfo requestedBluetooth(Context c){AudioDeviceInfo in=device(c,CarModeState.inputId,true),out=device(c,CarModeState.outputId,false);if(in!=null&&CarAudioTypes.bluetooth(in.getType()))return in;if(out!=null&&CarAudioTypes.bluetooth(out.getType())&&CarModeState.inputId==0)return out;return null;}
    static AudioDeviceInfo communicationFor(Context c,AudioDeviceInfo requested){if(requested==null)return null;AudioManager a=manager(c);if(Build.VERSION.SDK_INT>=31){for(AudioDeviceInfo d:a.getAvailableCommunicationDevices())if(d.getId()==requested.getId()||d.getType()==requested.getType()&&d.getProductName().toString().equals(requested.getProductName().toString()))return d;}else for(AudioDeviceInfo d:a.getDevices(AudioManager.GET_DEVICES_OUTPUTS))if(d.getType()==requested.getType()&&d.getProductName().toString().equals(requested.getProductName().toString()))return d;return null;}
    static boolean communicationConfirmed(Context c){AudioDeviceInfo wanted=requestedBluetooth(c);if(wanted==null)return true;if(Build.VERSION.SDK_INT>=31){AudioDeviceInfo expected=communicationFor(c,wanted),actual=manager(c).getCommunicationDevice();return expected!=null&&actual!=null&&actual.getId()==expected.getId();}return legacyScoConnected;}
    static synchronized void release(Context c){AudioManager a=manager(c);if(previousMode==null)return;try{if(Build.VERSION.SDK_INT>=31){if(previousMode==AudioManager.MODE_IN_COMMUNICATION&&previousCommunication!=null)a.setCommunicationDevice(previousCommunication);else a.clearCommunicationDevice();}else{a.stopBluetoothSco();a.setBluetoothScoOn(false);legacyScoConnected=false;}a.setMode(previousMode);}finally{previousMode=null;previousCommunication=null;routeStatus="Rota anterior restaurada; use o teste local para confirmar o microfone.";}}
    static synchronized boolean configure(Context c){
        AudioManager a=manager(c);
        if(!CarModeState.active||CarModeState.inputId==0&&CarModeState.outputId==0){release(c);return a.getMode()==AudioManager.MODE_IN_COMMUNICATION;}
        AudioDeviceInfo requested=requestedBluetooth(c);
        if(previousMode==null){previousMode=a.getMode();if(Build.VERSION.SDK_INT>=31)previousCommunication=a.getCommunicationDevice();}
        if(requested!=null){AudioDeviceInfo sink=communicationFor(c,requested);if(sink==null)throw new IllegalStateException("Bluetooth não disponível para comunicação HFP/SCO. RX pode funcionar somente como reprodução.");a.setMode(AudioManager.MODE_IN_COMMUNICATION);if(Build.VERSION.SDK_INT>=31){if(!a.setCommunicationDevice(sink))throw new IllegalStateException("Android recusou o dispositivo de comunicação.");}else if(!legacyScoConnected){a.startBluetoothSco();a.setBluetoothScoOn(true);}routeStatus=communicationConfirmed(c)?"Comunicação Bluetooth selecionada; captura ainda precisa ser verificada.":"Aguardando confirmação de comunicação Bluetooth…";return true;}
        if(Build.VERSION.SDK_INT>=31)a.clearCommunicationDevice();else{a.stopBluetoothSco();a.setBluetoothScoOn(false);legacyScoConnected=false;}a.setMode(AudioManager.MODE_NORMAL);routeStatus="Rota solicitada; confirme a entrada no teste local.";return false;
    }
    static void output(Context c,AudioTrack t){if(!CarModeState.active)return;AudioDeviceInfo d=device(c,CarModeState.outputId,false);AudioDeviceInfo bt=requestedBluetooth(c);if(bt!=null)d=communicationFor(c,bt);if(d!=null&&!t.setPreferredDevice(d))throw new IllegalStateException("Saída solicitada recusada.");report(c,t.getRoutedDevice(),"output");t.addOnRoutingChangedListener(r->report(c,((AudioTrack)r).getRoutedDevice(),"output"),null);}
    static void input(Context c,AudioRecord r){if(!CarModeState.active)return;observedInput="Não verificado nesta captura";observedInputId=0;observedInputType=0;AudioDeviceInfo d=device(c,CarModeState.inputId,true);if(d!=null&&!CarAudioTypes.microphone(d.getType()))throw new IllegalStateException("Esta interface não é um microfone físico selecionável.");if(d!=null&&!r.setPreferredDevice(d))throw new IllegalStateException("Microfone solicitado recusado.");report(c,r.getRoutedDevice(),"input");r.addOnRoutingChangedListener(x->report(c,((AudioRecord)x).getRoutedDevice(),"input"),null);}
    static void verifyCapture(Context c,AudioRecord r){if(!CarModeState.active)return;AudioDeviceInfo actual=r.getRoutedDevice();report(c,actual,"input");AudioDeviceInfo wanted=device(c,CarModeState.inputId,true),bt=requestedBluetooth(c);if(bt!=null){if(!communicationConfirmed(c)||actual==null||!CarAudioTypes.bluetooth(actual.getType())||!actual.getProductName().toString().equals(bt.getProductName().toString()))throw new IllegalStateException("Microfone Bluetooth não confirmado. TX bloqueado; selecione Padrão do Android para usar o celular.");}else if(wanted!=null&&(actual==null||actual.getId()!=wanted.getId()))throw new IllegalStateException("A captura não utiliza o microfone solicitado. TX bloqueado.");}
    static JSONObject diagnostic(Context c){JSONObject j=new JSONObject();try{AudioManager a=manager(c);j.put("requestedInput",describe(device(c,CarModeState.inputId,true))).put("requestedOutput",describe(device(c,CarModeState.outputId,false))).put("communicationDevice",Build.VERSION.SDK_INT>=31?describe(a.getCommunicationDevice()):legacyScoConnected?"SCO conectado (API legada)":"SCO não confirmado").put("communicationConfirmed",communicationConfirmed(c)).put("observedInput",observedInput).put("observedInputType",observedInputType).put("observedInputId",observedInputId).put("routeStatus",routeStatus);}catch(Exception e){try{j.put("routeStatus","Permissão Bluetooth/áudio necessária: "+e.getMessage());}catch(Exception ignored){}}return j;}
    private static void report(Context c,AudioDeviceInfo d,String direction){String name=describe(d);boolean changed;if("input".equals(direction)){changed=!name.equals(observedInput);observedInput=name;observedInputId=d==null?0:d.getId();observedInputType=d==null?0:d.getType();}else{changed=!name.equals(observedOutput);observedOutput=name;}if(!changed)return;try{JSONObject data=new JSONObject().put("direction",direction).put("confirmed",d!=null).put("id",d==null?0:d.getId()).put("type",d==null?0:d.getType()).put("name",name);c.sendBroadcast(new Intent(RadioSessionService.ACTION_EVENT).setPackage(c.getPackageName()).putExtra(RadioSessionService.EXTRA_EVENT,"carAudio").putExtra(RadioSessionService.EXTRA_DATA,data.toString()));}catch(Exception ignored){}}
}
